import{_ as e,c as t,aU as i,a as r}from"./chunks/framework.DIXiA2XH.js";const l="/assets/PosterEditor2.birgFuqi.png",o="/assets/PosterEditor1.DQ8OisvT.png",u=JSON.parse('{"title":"业余时间开发了个海报编辑器","description":"","frontmatter":{},"headers":[],"relativePath":"note/my-diary/业余时间开发了个海报编辑器.md","filePath":"note/my-diary/业余时间开发了个海报编辑器.md","lastUpdated":1784550594000}'),s={name:"note/my-diary/业余时间开发了个海报编辑器.md"};function p(n,a,d,c,h,_){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="业余时间开发了个海报编辑器" tabindex="-1">业余时间开发了个海报编辑器 <a class="header-anchor" href="#业余时间开发了个海报编辑器" aria-label="Permalink to &quot;业余时间开发了个海报编辑器&quot;">​</a></h1><h2 id="需求" tabindex="-1">需求 <a class="header-anchor" href="#需求" aria-label="Permalink to &quot;需求&quot;">​</a></h2><p>因为有时候需要写篇博客文章或者录制个教程视频。需要首图的海报，不然没办法发布，再一个就是一个好的海报还是可以挺高用户对文章的吸引力的，之前我都是在网上找的那种在线编辑器制作的，比如创可贴，Canvas这种海报工具网站，但是吧，有个问题是只能制作简单的海报，稍微复杂点的就需要充值，但是对我也没啥影响，因为我一直都是用的最基础的，一直在使用黑底白字，简直是基础中的超基础，因为简单嘛，文字也足够醒目。这倒是也没啥，唯一让我感到不爽的是过几天就需要登录，这个真实贼烦，所以我就想着，反正我用的都是最简单的，为毛不自己用代码实现一个工具，直接导出图片的。 其实需求也很简单，就是固定的海报尺寸，比如公众号海报尺寸是首图：<code>900px*383px</code>，B站封面及视频：<code>1280px*800px</code>，小红薯竖版封面：<code>1242px*1660px（3:4）</code>，然后可以打上标题，标题自动居中，字体颜色白色，背景黑色即可。</p><p>目的：开箱即用</p><h2 id="实现第一版" tabindex="-1">实现第一版 <a class="header-anchor" href="#实现第一版" aria-label="Permalink to &quot;实现第一版&quot;">​</a></h2><p>然后就花了2个小时时间写了第一版的编辑器，及其的简单。如图示例。然后我后面文章所以的封面图片都是用这个生成的，也还可以。</p><p><img src="'+l+'" alt=""></p><h2 id="实现第二版" tabindex="-1">实现第二版 <a class="header-anchor" href="#实现第二版" aria-label="Permalink to &quot;实现第二版&quot;">​</a></h2><p>但是就在前几天突然有了个想法，想再优化一版。因为感觉之前的那一版太素了，没有吸引力，那么大部分人对图片的第一吸引力在哪呢？我感觉应该是背景和字体相关，所以初步的需求就有了。</p><p>新需求如下：</p><ul><li>支持背景图</li><li>背景图可以模糊</li><li>支持文字</li><li>文字自动居中</li><li>文字支持修改字体大小</li><li>文字支持修改字体样式</li><li>背景图支持透明度</li><li>背景图支持更改背景颜色</li><li>支持导出PNG，JPG图片</li><li>增加一键更改背景图片，高清图，本地图片</li><li>支持修改文字颜色</li><li>支持自定义图片尺寸</li><li>预设多个自定义尺寸</li></ul><p><img src="'+o+'" alt=""></p><p>这样看，两个图片对比是不是就显的后者更加的强烈。</p><h2 id="海报编辑器地址" tabindex="-1">海报编辑器地址 <a class="header-anchor" href="#海报编辑器地址" aria-label="Permalink to &quot;海报编辑器地址&quot;">​</a></h2><p><a href="https://tool.share888.top/#/poster" target="_blank" rel="noreferrer">https://tool.share888.top/#/poster</a></p><p>虽然还有一些bug存在，后面有空再优化吧。</p>',16)])])}const f=e(s,[["render",p]]);export{u as __pageData,f as default};
